00043 namespace vtm {
00044 
00045 typedef int PosType;
00046 typedef uint32_t SizeType;
00047 struct Position
00048 {
00049   PosType x;
00050   PosType y;
00051 
00052   Position()                                   : x(0),  y(0)  { }
00053   Position(const PosType _x, const PosType _y) : x(_x), y(_y) { }
00054 
00055   bool operator!=(const Position &other)  const { return x != other.x || y != other.y; }
00056   bool operator==(const Position &other)  const { return x == other.x && y == other.y; }
00057 
00058   Position offset(const Position pos)                 const { return Position(x + pos.x, y + pos.y); }
00059   Position offset(const PosType _x, const PosType _y) const { return Position(x + _x   , y + _y   ); }
00060   void     repositionTo(const Position newPos)              { x  = newPos.x; y  = newPos.y; }
00061   void     relativeTo  (const Position origin)              { x -= origin.x; y -= origin.y; }
00062 
00063   Position operator-( const Position &other )         const { return{ x - other.x, y - other.y }; }
00064 };
00065 
00066 struct Size
00067 {
00068   SizeType width;
00069   SizeType height;
00070 
00071   Size()                                              : width(0),      height(0)       { }
00072   Size(const SizeType _width, const SizeType _height) : width(_width), height(_height) { }
00073 
00074   bool operator!=(const Size &other)      const { return (width != other.width) || (height != other.height); }
00075   bool operator==(const Size &other)      const { return (width == other.width) && (height == other.height); }
00076   uint32_t area()                             const { return (uint32_t) width * (uint32_t) height; }
00077 #if REUSE_CU_RESULTS_WITH_MULTIPLE_TUS
00078   void resizeTo(const Size newSize)             { width = newSize.width; height = newSize.height; }
00079 #endif
00080 };
00081 
00082 struct Area : public Position, public Size
00083 {
00084   Area()                                                                         : Position(),       Size()       { }
00085   Area(const Position &_pos, const Size &_size)                                  : Position(_pos),   Size(_size)  { }
00086   Area(const PosType _x, const PosType _y, const SizeType _w, const SizeType _h) : Position(_x, _y), Size(_w, _h) { }
00087 
00088         Position& pos()                           { return *this; }
00089   const Position& pos()                     const { return *this; }
00090         Size&     size()                          { return *this; }
00091   const Size&     size()                    const { return *this; }
00092 
00093   const Position& topLeft()                 const { return *this; }
00094         Position  topRight()                const { return { (PosType) (x + width - 1), y                          }; }
00095         Position  bottomLeft()              const { return { x                        , (PosType) (y + height - 1) }; }
00096         Position  bottomRight()             const { return { (PosType) (x + width - 1), (PosType) (y + height - 1) }; }
00097         Position  center()                  const { return { (PosType) (x + width / 2), (PosType) (y + height / 2) }; }
00098 
00099   bool contains(const Position &_pos)       const { return (_pos.x >= x) && (_pos.x < (x + width)) && (_pos.y >= y) && (_pos.y < (y + height)); }
00100   bool contains(const Area &_area)          const { return contains(_area.pos()) && contains(_area.bottomRight()); }
00101 
00102   bool operator!=(const Area &other)        const { return (Size::operator!=(other)) || (Position::operator!=(other)); }
00103   bool operator==(const Area &other)        const { return (Size::operator==(other)) && (Position::operator==(other)); }
00104 };
00105 
00106 struct UnitScale
00107 {
00108   UnitScale()                 : posx( 0), posy( 0), area(posx+posy) {}
00109   UnitScale( int sx, int sy ) : posx(sx), posy(sy), area(posx+posy) {}
00110   int posx;
00111   int posy;
00112   int area;
00113 
00114   template<typename T> T scaleHor ( const T &in ) const { return in >> posx; }
00115   template<typename T> T scaleVer ( const T &in ) const { return in >> posy; }
00116   template<typename T> T scaleArea( const T &in ) const { return in >> area; }
00117 
00118   Position scale( const Position &pos  ) const { return { pos.x >> posx, pos.y >> posy }; }
00119   Size     scale( const Size     &size ) const { return { size.width >> posx, size.height >> posy }; }
00120   Area     scale( const Area    &_area ) const { return Area( scale( _area.pos() ), scale( _area.size() ) ); }
00121 };
00122 
