00125 namespace std
00126 {
00127   template <>
00128   struct hash<vtm::Position> : public unary_function<vtm::Position, uint64_t>
00129   {
00130     uint64_t operator()(const vtm::Position& value) const
00131     {
00132       return (((uint64_t)value.x << 32) + value.y);
00133     }
00134   };
00135 
00136   template <>
00137   struct hash<vtm::Size> : public unary_function<vtm::Size, uint64_t>
00138   {
00139     uint64_t operator()(const vtm::Size& value) const
00140     {
00141       return (((uint64_t)value.width << 32) + value.height);
00142     }
00143   };
00144 }
