00146 namespace vtm {
00147 
00148 inline size_t rsAddr(const Position &pos, const uint32_t stride, const UnitScale &unitScale )
00149 {
00150   return (size_t)(stride >> unitScale.posx) * (size_t)(pos.y >> unitScale.posy) + (size_t)(pos.x >> unitScale.posx);
00151 }
00152 
00153 inline size_t rsAddr(const Position &pos, const Position &origin, const uint32_t stride, const UnitScale &unitScale )
00154 {
00155   return (stride >> unitScale.posx) * ((pos.y - origin.y) >> unitScale.posy) + ((pos.x - origin.x) >> unitScale.posx);
00156 }
00157 
00158 inline size_t rsAddr(const Position &pos, const uint32_t stride )
00159 {
00160   return stride * (size_t)pos.y + (size_t)pos.x;
00161 }
00162 
00163 inline size_t rsAddr(const Position &pos, const Position &origin, const uint32_t stride )
00164 {
00165   return stride * (pos.y - origin.y) + (pos.x - origin.x);
00166 }
00167 
00168 inline Area clipArea(const Area &_area, const Area &boundingBox)
00169 {
00170   Area area = _area;
00171 
00172   if (area.x + area.width > boundingBox.x + boundingBox.width)
00173   {
00174     area.width = boundingBox.x + boundingBox.width - area.x;
00175   }
00176 
00177   if (area.y + area.height > boundingBox.y + boundingBox.height)
00178   {
00179     area.height = boundingBox.y + boundingBox.height - area.y;
00180   }
00181 
00182   return area;
00183 }
00184 
