00186 class SizeIndexInfo
00187 {
00188 public:
00189   SizeIndexInfo(){}
00190   virtual ~SizeIndexInfo(){}
00191   SizeType numAllWidths()               { return (SizeType)m_idxToSizeTab.size(); }
00192   SizeType numAllHeights()              { return (SizeType)m_idxToSizeTab.size(); }
00193   SizeType numWidths()                  { return (SizeType)m_numBlkSizes; }
00194   SizeType numHeights()                 { return (SizeType)m_numBlkSizes; }
00195   SizeType sizeFrom( SizeType idx )     { return m_idxToSizeTab[idx]; }
00196   SizeType idxFrom( SizeType size )     { CHECKD( m_sizeToIdxTab[size] == std::numeric_limits<SizeType>::max(), "Index of given size does NOT EXIST!" ); return m_sizeToIdxTab[size]; }
00197   bool     isCuSize( SizeType size )    { return m_isCuSize[size]; }
00198   virtual void init( SizeType maxSize ) {}
00199 
00200 protected:
00201 
00202   void xInit()
00203   {
00204     m_isCuSize.resize( m_sizeToIdxTab.size(), false );
00205 
00206     std::vector<SizeType> grpSizes;
00207 
00208     for( int i = 0, n = 0; i < m_sizeToIdxTab.size(); i++ )
00209     {
00210       if( m_sizeToIdxTab[i] != std::numeric_limits<SizeType>::max() )
00211       {
00212         m_sizeToIdxTab[i] = n;
00213         m_idxToSizeTab.push_back( i );
00214         n++;
00215       }
00216 
00217       if( m_sizeToIdxTab[i] != std::numeric_limits<SizeType>::max() && m_sizeToIdxTab[i >> 1] != std::numeric_limits<SizeType>::max() && i >= 4 )
00218       {
00219         m_isCuSize[i] = true;
00220       }
00221 
00222       // collect group sizes (for coefficient group coding)
00223       SizeType grpSize = i >> ( ( i & 3 ) != 0 ? 1 : 2 );
00224       if( m_sizeToIdxTab[i] != std::numeric_limits<SizeType>::max() && m_sizeToIdxTab[grpSize] == std::numeric_limits<SizeType>::max() )
00225       {
00226         grpSizes.push_back( grpSize );
00227       }
00228     }
00229 
00230     m_numBlkSizes = (SizeType)m_idxToSizeTab.size();
00231 
00232     for( SizeType grpSize : grpSizes )
00233     {
00234       if( grpSize > 0 && m_sizeToIdxTab[grpSize] == std::numeric_limits<SizeType>::max() )
00235       {
00236         m_sizeToIdxTab[grpSize] = (SizeType)m_idxToSizeTab.size();
00237         m_idxToSizeTab.push_back( grpSize );
00238       }
00239     }
00240   };
00241 
00242   std::vector<bool    > m_isCuSize;
00243   int                   m_numBlkSizes; // as opposed to number all sizes, which also contains grouped sizes
00244   std::vector<SizeType> m_sizeToIdxTab;
00245   std::vector<SizeType> m_idxToSizeTab;
00246 };
00247 
00248 class SizeIndexInfoLog2 : public SizeIndexInfo
00249 {
00250 public:
00251   SizeIndexInfoLog2(){}
00252   ~SizeIndexInfoLog2(){};
00253 
00254   void init( SizeType maxSize )
00255   {
00256     for( int i = 0, n = 0; i <= maxSize; i++ )
00257     {
00258       SizeType val = std::numeric_limits<SizeType>::max();
00259       if( i == ( 1 << n ) )
00260       {
00261         n++;
00262         val = i;
00263       }
00264       m_sizeToIdxTab.push_back( val );
00265     }
00266     SizeIndexInfo::xInit();
00267   }
00268 };
